        discount = 0.0

        if promo_code == "SUMMER10":
            discount += subtotal * 0.10
        elif promo_code == "SAVE20":
            discount += subtotal * 0.20
        elif promo_code == "FIXED15":
            discount += min(15.0, subtotal)

